/**
 * The help card beside the questions of FaqSplit: a title, a line of text, the ways to reach the team (icon,
 * name, one line) and a link.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import type { Question, FaqSplitLabels } from "../blocks/faq-split.types";
import type { Feature } from "../blocks/feature-grid.types";

export type FaqHelpProps = {
  labels: FaqSplitLabels;
  channels: Feature[];
};

export function FaqHelp({ labels, channels }: FaqHelpProps) {
  return (
    <Block
      tag="aside"
      className="rounded bg-card inset-ring inset-ring-border flex flex-col gap-6 p-6"
      aria-label={labels.asideTitle}
      data-testid="faq-help"
    >
      <Stack gap="2">
        <Text size="lg" weight="semibold">
          {labels.asideTitle}
        </Text>
        <Text size="sm" className="text-muted-foreground">
          {labels.asideText}
        </Text>
      </Stack>
      <List className="m-0 flex list-none flex-col gap-4 p-0">
        {(channels ?? []).map((c) => (
          <ListItem key={c.id} className="flex items-start gap-4" data-testid="faq-channel">
            <Box className="flex size-10 shrink-0 items-center justify-center rounded bg-muted">
              <LucideIcon name={c.icon} size={20} />
            </Box>
            <Stack gap="0">
              <Text size="sm" weight="semibold">
                {c.title}
              </Text>
              <Text size="xs" className="text-muted-foreground">
                {c.text}
              </Text>
            </Stack>
          </ListItem>
        ))}
      </List>
      <Link href="#/contact" variant="default" size="sm" className="font-medium">
        {labels.asideCta}
        <LucideIcon name="arrow-right" size={16} />
      </Link>
    </Block>
  );
}
